fixtures.tests/report-path.test.mjs:
import { mkdirSync, mkdtempSync, symlinkSync } from "node:fs";
import { tmpdir } from "node:os";
import { join } from "node:path";
import { expect, it } from "vitest";
import { resolveReportPath } from "../src/report-path.mjs";

const root = mkdtempSync(join(tmpdir(), "run-root-"));

it("accepts a path inside the root", () => {
  mkdirSync(join(root, "reports"), { recursive: true });
  expect(resolveReportPath(root, "reports")).toBe(join(root, "reports"));
});

it("rejects a parent-directory escape", () => {
  expect(() => resolveReportPath(root, "../escape.md")).toThrow(/escapes run root/u);
});

it("rejects an absolute path outside the root", () => {
  expect(() => resolveReportPath(root, "/etc/passwd")).toThrow(/escapes run root/u);
});

it("rejects a sibling directory sharing the root prefix", () => {
  mkdirSync(`${root}-2`, { recursive: true });
  expect(() => resolveReportPath(root, `${root}-2`)).toThrow(/escapes run root/u);
});

it("rejects an existing symlink that escapes the root", () => {
  const outside = mkdtempSync(join(tmpdir(), "outside-"));
  mkdirSync(join(outside, "target"), { recursive: true });
  symlinkSync(join(outside, "target"), join(root, "linked"));
  expect(() => resolveReportPath(root, "linked")).toThrow(/escapes run root/u);
});

