-export function resolveReportPath(runRoot, requested) {
-  throw new Error("not implemented");
+import { realpathSync } from "node:fs";
+import { resolve, sep } from "node:path";
+
+export function resolveReportPath(runRoot, requested) {
+  // Clause 1: compare against the real path of the root.
+  const root = realpathSync(resolve(runRoot));
+  const absolute = resolve(root, requested);
+
+  let probe;
+  try {
+    // Clause 2: resolve symlinks so a linked path cannot escape the root.
+    probe = realpathSync(absolute);
+  } catch {
+    // Clause 3: the report file does not exist yet, so use the resolved path.
+    probe = absolute;
+  }
+
+  // Clause 4: separator-aware boundary comparison.
+  if (probe !== root && !probe.startsWith(root + sep)) {
+    // Clause 5: rejection raises rather than clamping.
+    throw new Error(`path escapes run root: ${requested}`);
+  }
+  return probe;
 }

